CREATE VIEW "coe_results" AS ((select "month", "bidding_no", "vehicle_class", "quota", "bids_success", "bids_received", "premium" from "coe") union all (select "month", "bidding_no", "vehicle_class", "quota", "bids_success", "bids_received", "premium" from "coe_interim_results" where not exists (select "month" from "coe" where (("coe"."month" = "coe_interim_results"."month") and ("coe"."bidding_no" = "coe_interim_results"."bidding_no")))));